/* Supabase cloud bridge. Offline source is kept separately. */
window.TMCloud=(()=>{
 const url='https://vcvqoonpcojnlidqhwmp.supabase.co',key='sb_publishable_WDVIIs8ZnOe95NysIFUpEw_RdnuImAB';
 const rawSet=Storage.prototype.setItem,rawRemove=Storage.prototype.removeItem;
 const mapping={amc_technicians:['technician','array'],amc_day_allocations:['allocation_day','days'],amc_callouts:['callout','array'],amc_leaves:['leave','array'],amc_leave_requests:['leave_request','array'],amc_overtime_records:['overtime','array'],amc_bahrain_holidays:['holiday','array'],amc_saturday_settings:['saturday_settings','single'],amc_callout_roster:['callout_roster','single'],amc_team_settings:['team_settings','single']};
 let versions={},baseline={},pending=Promise.resolve(),dirty=0,failed=false,refreshing=null;
 const readSession=()=>{try{return JSON.parse(sessionStorage.getItem('amc_auth_session')||localStorage.getItem('amc_auth_session')||'null')}catch{return null}};
 const profile=p=>({id:p.id,username:p.username,name:p.name,role:p.role,status:p.status,technicianNumber:p.technician_id||'',createdAt:p.created_at});
 const banner=(text,error=false)=>{let el=document.getElementById('cloud-status');if(!el){el=document.createElement('div');el.id='cloud-status';el.setAttribute('role','status');el.style.cssText='position:fixed;bottom:12px;left:12px;z-index:99999;padding:10px 14px;border-radius:8px;font:13px system-ui;max-width:calc(100vw - 24px);box-sizing:border-box';document.body.append(el)}el.textContent=text;el.style.background=error?'#9f2020':'#145c4a';el.style.color='white';el.hidden=false;clearTimeout(el.dismissTimer);if(!error&&!text.startsWith('Saving'))el.dismissTimer=setTimeout(()=>{el.hidden=true;},6000);};
 function showCredentials(accounts){if(!accounts?.length)return;const overlay=document.createElement('div');overlay.className='cloud-credential-overlay';const dialog=document.createElement('section');dialog.className='cloud-credential-dialog';dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-label','New technician logins');const title=document.createElement('h2');title.textContent='Technician logins created';const hint=document.createElement('p');hint.textContent='Copy these credentials before closing. Generated passwords are shown only once.';const text=accounts.map(a=>a.name+' (ID '+a.technician_id+')\nUsername: '+a.username+'\nPassword: '+a.password).join('\n\n');const details=document.createElement('pre');details.textContent=text;const actions=document.createElement('div');actions.className='cloud-credential-actions';const copy=document.createElement('button');copy.className='btn btn-primary';copy.textContent='Copy credentials';copy.onclick=async()=>{try{await navigator.clipboard.writeText(text);copy.textContent='Copied';}catch{copy.textContent='Select and copy the text above';}};const close=document.createElement('button');close.className='btn btn-outline';close.textContent='Done';close.onclick=()=>overlay.remove();actions.append(copy,close);dialog.append(title,hint,details,actions);overlay.append(dialog);document.body.append(overlay);copy.focus();}
 function authError(message){const error=Error(message);error.code='AUTH_REQUIRED';return error;}
 function clearSession(){rawRemove.call(localStorage,'amc_auth_session');rawRemove.call(sessionStorage,'amc_auth_session');}
 function reconnect(error){if(error.code!=='AUTH_REQUIRED')return;clearSession();if(!dirty&&!failed){location.reload();return;}banner('Session expired. Keep this tab open to preserve unsaved edits. Sign in in a new tab, then return here.',true);}
 function persist(session){const target=localStorage.getItem('amc_auth_session')?localStorage:sessionStorage;rawSet.call(target,'amc_auth_session',JSON.stringify(session));}
 async function renew(){if(refreshing)return refreshing;refreshing=(async()=>{const s=readSession();if(!s?.refresh_token)throw authError('Please sign in to continue.');const r=await fetch(url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});const d=await r.json();if(!r.ok){if(r.status===400||r.status===401||r.status===403)throw authError('Your session expired. Please sign in again.');throw Error('Cannot refresh the connection. Please try again.');}const next={...s,token:d.access_token,refresh_token:d.refresh_token,expires_at:d.expires_at};persist(next);return next;})().finally(()=>refreshing=null);return refreshing;}
 async function api(action,body={},retry=true){let session=action==='login'?null:readSession();if(action!=='login'&&!session?.cloud)throw authError('Please sign in to continue.');if(action!=='login'&&session?.expires_at&&session.expires_at*1000<Date.now()+60000)session=await renew();const r=await fetch(url+'/functions/v1/tm-api',{method:'POST',headers:{apikey:key,'Content-Type':'application/json',...(session?.token?{Authorization:'Bearer '+session.token}:{})},body:JSON.stringify({action,...body}),signal:AbortSignal.timeout(25000)});const d=await r.json().catch(()=>({error:'Cloud service is not deployed or returned an invalid response.'}));if(r.status===401&&action!=='login'&&retry){await renew();return api(action,body,false)}if(r.status===401&&action!=='login')throw authError('Your session expired. Please sign in again.');if(!r.ok)throw Error(d.error||'Cloud request failed');return d;}
 const entries=(value,shape)=>shape==='days'?Object.entries(value||{}):shape==='single'?[['default',value||{}]]:(value||[]).map(r=>[String(r.id),r]);
 const materialize=snapshot=>{const values={};for(const [k,[kind,shape]] of Object.entries(mapping)){const records=snapshot.records.filter(r=>r.kind===kind);values[k]=shape==='days'?Object.fromEntries(records.map(r=>[r.id,r.payload])):shape==='single'?(records[0]?.payload||{}):records.map(r=>r.payload);}return values;};
 function hydrate(snapshot){const values=materialize(snapshot);versions={};snapshot.records.forEach(r=>versions[r.kind+':'+r.id]=r.version);for(const [k,v] of Object.entries(values)){rawSet.call(localStorage,k,JSON.stringify(v));baseline[k]=v;}rawSet.call(localStorage,'amc_system_users',JSON.stringify(snapshot.users.map(profile)));const s=readSession();if(s)persist({...s,user:profile(snapshot.profile)});return values;}
 function install(){Storage.prototype.setItem=function(k,v){if(this!==localStorage||!mapping[k])return rawSet.call(this,k,v);const next=JSON.parse(v),[kind,shape]=mapping[k],previous=new Map(entries(baseline[k],shape)),incoming=new Map(entries(next,shape));const changes=[];for(const [id,payload] of incoming)if(JSON.stringify(payload)!==JSON.stringify(previous.get(id)))changes.push({kind,id,payload});for(const id of previous.keys())if(!incoming.has(id))changes.push({kind,id,deleted:true});rawSet.call(this,k,v);baseline[k]=next;if(!changes.length)return;dirty++;banner('Saving changes to Supabase…');pending=pending.then(async()=>{if(failed)throw Error('A previous save failed. Keep this tab open and resolve it before continuing.');for(const c of changes){const result=await api('save_record',{...c,version:versions[kind+':'+c.id]||0});if(result.credentials?.length)showCredentials(result.credentials);if(result.accountWarning)banner(result.accountWarning,true);if(c.deleted)delete versions[kind+':'+c.id];else versions[kind+':'+c.id]=result.record.version;}}).then(()=>{dirty--;banner(dirty?'Saving changes to Supabase…':'Saved to Supabase');}).catch(error=>{failed=true;dirty--;banner('NOT SAVED: '+error.message+' Your local edits remain in this tab.',true);});};
  window.addEventListener('beforeunload',e=>{if(dirty||failed){e.preventDefault();e.returnValue=''}});
  setInterval(async()=>{if(!readSession()?.cloud)return;if(dirty||failed||document.hidden||document.activeElement?.matches('input,textarea,[contenteditable=true]')||document.querySelector('.modal-backdrop,.modal-overlay,.cloud-credential-overlay,[data-floating-panel]'))return;try{const snapshot=await api('snapshot');const next=materialize(snapshot);const users=snapshot.users.map(profile);if(JSON.stringify(next)!==JSON.stringify(baseline)||JSON.stringify(users)!==localStorage.getItem('amc_system_users')){hydrate(snapshot);location.reload();}}catch(error){if(error.code==='AUTH_REQUIRED'){reconnect(error);return;}banner('Cloud connection: '+error.message,true)}},15000);
 }
 async function start(){const s=readSession();if(!s?.cloud){for(const k of [...Object.keys(mapping),'amc_system_users'])rawRemove.call(localStorage,k);return;}try{hydrate(await api('snapshot'));install();banner('Connected to Supabase');}catch(error){if(error.code==='AUTH_REQUIRED')clearSession();banner(error.message,true);}}
 async function login(username,password,remember){const d=await api('login',{username,password});const s={cloud:true,user:profile(d.profile),token:d.session.access_token,refresh_token:d.session.refresh_token,expires_at:d.session.expires_at,createdAt:new Date().toISOString()};rawRemove.call(localStorage,'amc_auth_session');rawRemove.call(sessionStorage,'amc_auth_session');rawSet.call(remember?localStorage:sessionStorage,'amc_auth_session',JSON.stringify(s));hydrate(await api('snapshot'));location.reload();}
 return {start,login,api,banner,profile,showCredentials};
})();
